// Real9 descriptor constructors,460910,40b1c0,40cc90,41f8f0.
// CRT DLL rand and417400's sector result are explicit recorded boundaries.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNativeFactoryConstructorOracle extends GhidraScript{
 static final long RET=0x12345000L,S=0x7fff0000L,B=0x5c5e38L,A=0x70000000L,RAND=A+0x10000;
 long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}
 void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}
 void resume(EmulatorHelper e)throws Exception{long s=e.readRegister("ESP").longValue(),r=read(e,s,4);e.writeRegister("ESP",s+4);if(!e.run(toAddr(r),null,monitor))throw new Exception(e.getLastError());}
 public void run()throws Exception{long[]ctors={0x40cd20,0x40b4e0,0x40b250,0x40c810,0x40bac0,0x40c810,0x40c810,0x40c810,0x40c820};try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int s=0;s<72;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{int k=s%9,mp=s/9%2,hp=100+s*11;byte[]m=new byte[900];java.util.Arrays.fill(m,(byte)255);e.writeMemory(toAddr(A+4096),m);e.writeMemory(toAddr(B),new byte[88]);put(e,B,2,400);put(e,B+2,2,500);put(e,B+4,1,k);put(e,B+5,1,0xab);put(e,B+6,1,(s*13)&0xe0);put(e,B+0x10,1,0xbc);put(e,B+0x3e,1,0xa5+s);put(e,B+0x24,4,123456);put(e,B+0x1c,2,hp);put(e,B+0x1e,2,hp);put(e,B+0x18,4,A+4096);put(e,A+1024+8,1,s%4);put(e,0x622dc4,1,mp);put(e,0x4740ac,4,RAND);for(int i=0;i<5;i++)put(e,0x622cdc+i*4,4,s*(i+1)+i+1);int[]off={0x622d68,0x622d64,0x622d6c,0x622d70};for(int i=0;i<4;i++){put(e,off[i],2,1000+i*100+s);put(e,off[i]+2,2,2000+i*100+s);}for(long p:new long[]{RET,RAND,0x417400})e.setBreakpoint(toAddr(p));e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,B);put(e,S+8,4,0x498c78+k*76);if(!e.run(toAddr(ctors[k]),null,monitor))throw new Exception(e.getLastError());int draws=0,stops=0;while(e.readRegister("EIP").longValue()!=RET){if(++stops>2)throw new Exception("too many stops");if(e.readRegister("EIP").longValue()==RAND){draws++;e.writeRegister("EAX",s*31+0x1234);}else e.writeRegister("EAX",A+1024);resume(e);}out.print("{\"scenario\":"+s+",\"kind\":"+k+",\"mp\":"+mp+",\"style5\":"+read(e,B+5,1)+",\"flags6\":"+read(e,B+6,1)+",\"field10\":"+read(e,B+16,1)+",\"field11\":"+read(e,B+17,1)+",\"clock3e\":"+read(e,B+62,1)+",\"state45\":"+read(e,B+69,1)+",\"work\":"+(int)read(e,B+36,4)+",\"maximum\":"+(short)read(e,B+28,2)+",\"hp\":"+(short)read(e,B+30,2)+",\"draws\":"+draws);for(int i=0;i<5;i++)out.print(",\"r"+i+"\":"+read(e,0x622cdc+i*4,4));out.println("}");}finally{e.dispose();}}}}
}
